#include <bits/stdc++.h>
using namespace std;
using LL = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    // 预处理 dp，dp[i][0] 偶数方案数，dp[i][1] 奇数方案数
    vector<vector<LL>> dp(n + 1, vector<LL>(2, 0));
    dp[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        dp[i][0] = dp[i-1][1] + 1;
        dp[i][1] = dp[i-1][0];
    }

    // 构建连续1段长度列表，首尾补0
    vector<int> tmp = {0};
    int i = 0;
    while (i < n) {
        if (a[i] == 1) {
            int cnt = 0;
            while (i < n && a[i] == 1) {
                cnt++;
                i++;
            }
            tmp.push_back(cnt);
        } else {
            tmp.push_back(0);
            i++;
        }
    }
    tmp.push_back(0);

    LL ans = 0;
    for (size_t j = 1; j + 1 < tmp.size(); j++) {
        if (tmp[j] == 0) {
            int L = tmp[j-1];
            int R = tmp[j+1];
            ans += dp[L][0] * dp[R][0] + dp[L][1] * dp[R][1];
        } else {
            int k = tmp[j];
            for (int t = 0; t < k; t++) {
                ans += (k - t + 1) / 2;
            }
        }
    }

    cout << ans << "\n";
    return 0;
}
